var e={"where.project":`プロジェクト`,"where.topic":`トピック`,"where.projectHelp":`プロジェクトは、同じテーマのトピックをまとめます。CLAUDE.md とメモリは、そのすべてのトピックに適用されます。`,"where.topicHelp":`トピックはこのセッションの作業フォルダです。Harness は、トピックの CLAUDE.md とメモリに加え、プロジェクトとグローバルのものも使って作業します。`,"where.move":`クリックして、このセッションを別のトピックへ移動します。`,"where.agent":`エージェント`,"where.agentHelp":`このセッションはエージェントのフォルダーで実行されます。Claude はエージェントの役割とメモリに加え、トピック、プロジェクト、全体のものを使って作業します。`};export{e as default};